@IsTest private class OwnedPermissionGrantProbe {
 @IsTest static void enabledGrantIsQueryable() {
  Id parentId = [SELECT Id FROM PermissionSet WHERE Name='OwnedReader'].Id;
  Id permissionId = [SELECT Id FROM CustomPermission WHERE DeveloperName='OwnedView'].Id;
  List<SetupEntityAccess> grants = [SELECT ParentId,SetupEntityId,SetupEntityType FROM SetupEntityAccess WHERE ParentId=:parentId AND SetupEntityId=:permissionId];
  Assert.areEqual(1,grants.size(),'Declared enabled permission has one junction');
  Assert.areEqual(parentId,grants[0].ParentId);
  Assert.areEqual(permissionId,grants[0].SetupEntityId);
  Assert.areEqual('CustomPermission',grants[0].SetupEntityType);
 }
 @IsTest static void disabledAndUnassignedControls() {
  Id parentId = [SELECT Id FROM PermissionSet WHERE Name='OwnedReader'].Id;
  Id permissionId = [SELECT Id FROM CustomPermission WHERE DeveloperName='OwnedEdit'].Id;
  Assert.areEqual(0,[SELECT COUNT() FROM SetupEntityAccess WHERE ParentId=:parentId AND SetupEntityId=:permissionId]);
  Assert.areEqual(0,[SELECT COUNT() FROM PermissionSetAssignment WHERE PermissionSetId=:parentId]);
  Assert.isFalse(FeatureManagement.checkPermission('OwnedView'));
 }
 @IsTest static void assignmentLifecycleControl() {
  Id parentId = [SELECT Id FROM PermissionSet WHERE Name='OwnedReader'].Id;
  PermissionSetAssignment assignment = new PermissionSetAssignment(AssigneeId=UserInfo.getUserId(),PermissionSetId=parentId);
  insert assignment;
  System.runAs(new User(Id=UserInfo.getUserId())) {
   Assert.isTrue(FeatureManagement.checkPermission('OwnedView'),'Assigned metadata permission is enabled');
   Assert.isFalse(FeatureManagement.checkPermission('OwnedEdit'));
   delete assignment;
   Assert.areEqual(0,[SELECT COUNT() FROM PermissionSetAssignment WHERE PermissionSetId=:parentId]);
  }
 }
 @IsTest static void assignedPermissionMatchesGrantQuery() {
  Id parentId = [SELECT Id FROM PermissionSet WHERE Name='OwnedReader'].Id;
  Id permissionId = [SELECT Id FROM CustomPermission WHERE DeveloperName='OwnedView'].Id;
  insert new PermissionSetAssignment(AssigneeId=UserInfo.getUserId(),PermissionSetId=parentId);
  Id userId = UserInfo.getUserId();
  List<PermissionSetAssignment> assignments = [SELECT PermissionSetId FROM PermissionSetAssignment WHERE AssigneeId=:userId AND PermissionSetId IN (SELECT ParentId FROM SetupEntityAccess WHERE SetupEntityId=:permissionId)];
  Assert.areEqual(1,assignments.size(),'Assigned permission and junction query agree');
  Assert.areEqual(parentId,assignments[0].PermissionSetId);
 }
}
